package com.lmspilot.course.api;
import com.lmspilot.course.domain.*; import com.lmspilot.support.api.ApiException; import com.lmspilot.support.security.CurrentUser; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.Instant; import java.util.*; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
record CreateDiscussionThreadRequest(@NotBlank @Size(max=240) String title,UUID lessonId,@NotBlank String content) {} record CreateDiscussionPostRequest(UUID parentPostId,@NotBlank String content) {} record ModerateDiscussionThreadRequest(DiscussionThreadStatus status,Boolean pinned) {} record DiscussionPostResponse(UUID id,UUID authorId,UUID parentPostId,String content,DiscussionPostStatus status,Instant createdAt) {} record DiscussionThreadResponse(UUID id,UUID courseId,UUID lessonId,String title,UUID authorId,DiscussionThreadStatus status,boolean pinned,int postCount,Instant createdAt,Instant updatedAt,List<DiscussionPostResponse> posts) {}
@Service @Transactional class DiscussionService { private final DiscussionThreadRepository threads; private final DiscussionPostRepository posts; DiscussionService(DiscussionThreadRepository t,DiscussionPostRepository p){threads=t;posts=p;} List<DiscussionThreadResponse> threads(UUID courseId){return threads.findAllByCourseIdAndStatusNotOrderByPinnedDescUpdatedAtDesc(courseId,DiscussionThreadStatus.HIDDEN).stream().map(t->view(t,List.of())).toList();} DiscussionThreadResponse createThread(UUID courseId,CreateDiscussionThreadRequest i){DiscussionThreadEntity t=new DiscussionThreadEntity();t.courseId=courseId;t.lessonId=i.lessonId();t.title=i.title().trim();t.authorId=user();threads.save(t);reply(t.id,new CreateDiscussionPostRequest(null,i.content()));return thread(t.id);} DiscussionThreadResponse thread(UUID id){DiscussionThreadEntity t=require(id);return view(t,posts.findAllByThreadIdAndStatusNotOrderByCreatedAtAsc(id,DiscussionPostStatus.DELETED).stream().map(this::post).toList());} DiscussionPostResponse reply(UUID id,CreateDiscussionPostRequest i){DiscussionThreadEntity t=require(id);if(t.status!=DiscussionThreadStatus.OPEN)throw new ApiException(HttpStatus.CONFLICT,"DISCUSSION_LOCKED","Chủ đề đã khóa");DiscussionPostEntity p=new DiscussionPostEntity();p.threadId=id;p.authorId=user();p.parentPostId=i.parentPostId();p.content=i.content().trim();posts.save(p);t.postCount++;t.updatedAt=Instant.now();threads.save(t);return post(p);} DiscussionThreadResponse moderateThread(UUID id,ModerateDiscussionThreadRequest i){DiscussionThreadEntity t=require(id);if(i.status()!=null)t.status=i.status();if(i.pinned()!=null)t.pinned=i.pinned();t.updatedAt=Instant.now();return view(threads.save(t),List.of());} void deletePost(UUID id){DiscussionPostEntity p=posts.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"DISCUSSION_POST_NOT_FOUND","Không tìm thấy bài viết"));p.status=DiscussionPostStatus.DELETED;p.content="";p.updatedAt=Instant.now();posts.save(p);} private DiscussionThreadEntity require(UUID id){return threads.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"DISCUSSION_THREAD_NOT_FOUND","Không tìm thấy chủ đề"));} private UUID user(){try{return CurrentUser.id();}catch(Exception e){return new UUID(0,1);}} private DiscussionPostResponse post(DiscussionPostEntity p){return new DiscussionPostResponse(p.id,p.authorId,p.parentPostId,p.content,p.status,p.createdAt);} private DiscussionThreadResponse view(DiscussionThreadEntity t,List<DiscussionPostResponse> p){return new DiscussionThreadResponse(t.id,t.courseId,t.lessonId,t.title,t.authorId,t.status,t.pinned,t.postCount,t.createdAt,t.updatedAt,p);} }
@RestController @RequestMapping("/api/v1/discussions") public class DiscussionApi { private final DiscussionService service; public DiscussionApi(DiscussionService s){service=s;} @GetMapping("/courses/{courseId}/threads") public List<DiscussionThreadResponse> threads(@PathVariable UUID courseId){return service.threads(courseId);} @PostMapping("/courses/{courseId}/threads") @ResponseStatus(HttpStatus.CREATED) public DiscussionThreadResponse create(@PathVariable UUID courseId,@Valid @RequestBody CreateDiscussionThreadRequest i){return service.createThread(courseId,i);} @GetMapping("/threads/{id}") public DiscussionThreadResponse thread(@PathVariable UUID id){return service.thread(id);} @PostMapping("/threads/{id}/posts") public DiscussionPostResponse reply(@PathVariable UUID id,@Valid @RequestBody CreateDiscussionPostRequest i){return service.reply(id,i);} @PatchMapping("/threads/{id}") public DiscussionThreadResponse moderate(@PathVariable UUID id,@RequestBody ModerateDiscussionThreadRequest i){return service.moderateThread(id,i);} @DeleteMapping("/posts/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id){service.deletePost(id);} }
